  "SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”": "SSH_MSG_CHANNEL_DATA (94)، کانال ۰: ۱ بایت، «w»",
  "SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown": "SSH_MSG_CHANNEL_DATA (94)، کانال ۰: ۱ بایت، «w»، بازگردانده شده برای نمایش",
  "SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”": "SSH_MSG_CHANNEL_DATA (94)، کانال ۰: ۱ بایت، «d»",
